div.script:
(function() {
    var cards = Array.prototype.slice.call(document.querySelectorAll('#wink-plan-cards .wink-plan-card'));
    var priceEl = document.getElementById('wink-detail-price-amount');
    var periodEl = document.getElementById('wink-detail-price-period');
    var btn = document.getElementById('wink-detail-request-btn');

    if (!cards.length) return;

    /* ── 1. Update live price display ── */
    function updatePrice(card) {
        var price = card.getAttribute('data-price');
        var period = card.getAttribute('data-period');
        if (priceEl && price) priceEl.textContent = 'AED ' + price;
        if (periodEl && period) periodEl.textContent = period;
    }

    /* ── 2. Show/hide cards by period; auto-select first visible ── */
    function filterCards(period) {
        var first = null;
        cards.forEach(function(c) {
            var match = c.getAttribute('data-period') === period;
            c.style.display = match ? '' : 'none';
            if (match && !first) first = c;
        });
        cards.forEach(function(c) { c.classList.remove('selected'); });
        if (first) { first.classList.add('selected'); updatePrice(first); }
    }

    /* ── 3. Period toggle buttons (server-rendered) ── */
    document.querySelectorAll('#wink-period-toggle .wink-period-btn').forEach(function(pbtn) {
        pbtn.addEventListener('click', function() {
            var period = pbtn.getAttribute('data-period');
            document.querySelectorAll('#wink-period-toggle .wink-period-btn').forEach(function(b) {
                b.classList.toggle('active', b === pbtn);
            });
            filterCards(period);
        });
    });

    /* ── 4. Card click: select + update price ── */
    cards.forEach(function(card) {
        card.addEventListener('click', function() {
            cards.forEach(function(c) { c.classList.remove('selected'); });
            card.classList.add('selected');
            updatePrice(card);
        });
    });

    /* ── 5. Request button routing ── */
    if (btn) {
        btn.addEventListener('click', function(e) {
            e.preventDefault();
            var sel = document.querySelector('#wink-plan-cards .wink-plan-card.selected');
            var rid = sel ? sel.getAttribute('data-pricing-id') : null;
            var sid = btn.getAttribute('data-service-id');
            if (sid) window.location.href = '/services/' + sid + '/request' + (rid ? '?plan=' + rid : '');
        });
    }

    /* ── 6. Initialise price from currently selected card ── */
    var initCard = document.querySelector('#wink-plan-cards .wink-plan-card.selected');
    if (initCard) updatePrice(initCard);
})();

                                            (function(){
                                                var container = document.getElementById('wink-new-emp-rows');

                                                // Remove row if multiple rows exist; clear all inputs if it is the last row
                                                function removeOrClear(row) {
                                                    var rows = container.querySelectorAll('.wink-new-emp-row');
                                                    if (rows.length > 1) {
                                                        container.removeChild(row);
                                                    } else {
                                                        row.querySelectorAll('input').forEach(function(inp) {
                                                            inp.value = '';
                                                            inp.dispatchEvent(new Event('input', {bubbles: true}));
                                                        });
                                                    }
                                                }

                                                // Bind existing Row 0 remove button
                                                container.querySelectorAll('.wink-rm-emp-row').forEach(function(btn) {
                                                    var row = btn.closest('.wink-new-emp-row');
                                                    btn.addEventListener('click', function() { removeOrClear(row); });
                                                });

                                                // Add Another — append a new row with its own remove button
                                                document.getElementById('wink-add-emp-row').addEventListener('click', function(){
                                                    var row = document.createElement('div');
                                                    row.className = 'wink-new-emp-row row g-2 mb-2 align-items-center';
                                                    row.innerHTML = [
                                                        '
',
                                                        '
',
                                                        '
',
                                                        '
',
                                                        '
'
                                                    ].join('');
                                                    row.querySelector('.wink-rm-emp-row').addEventListener('click', function() { removeOrClear(row); });
                                                    container.appendChild(row);
                                                });
                                            })();

t.script:
(function() {
    var box = document.getElementById('wink-gov-charge-box');
    if (!box) return;
    var govBase = parseFloat(box.dataset.govBase || '0');
    var govPerUnit = parseFloat(box.dataset.govPerUnit || '0');
    var amountEl = document.getElementById('wink-gov-amount-display');
    var noteEl = document.getElementById('wink-gov-emp-note');
    var countEl = document.getElementById('wink-gov-emp-count');
    var pluralEl = document.getElementById('wink-gov-emp-plural');

    function countEmployees() {
        var n = 0;
        // Count checked existing employees
        document.querySelectorAll('input[name="employee_ids"]:checked').forEach(function() { n++; });
        // Count new employee rows with a non-empty name
        document.querySelectorAll('input[name="new_emp_name[]"]').forEach(function(inp) {
            if ((inp.value || '').trim()) n++;
        });
        return Math.max(n, 1);
    }

    function updateGovAmount() {
        var n = countEmployees();
        var total = govBase + govPerUnit * n;
        amountEl.textContent = total.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
        if (n > 1 || countEl) {
            countEl.textContent = n;
            pluralEl.textContent = n === 1 ? '' : 's';
            noteEl.style.display = '';
        }
    }

    // Listen on existing employee checkboxes
    document.querySelectorAll('input[name="employee_ids"]').forEach(function(cb) {
        cb.addEventListener('change', updateGovAmount);
    });

    // Delegate new-row name inputs (rows added dynamically)
    var container = document.getElementById('wink-new-emp-rows');
    if (container) {
        container.addEventListener('input', function(e) {
            if (e.target && e.target.name === 'new_emp_name[]') updateGovAmount();
        });
        // Also recalculate when rows are removed (MutationObserver)
        new MutationObserver(updateGovAmount).observe(container, {childList: true});
    }

    updateGovAmount();
})();

div.script:
(function() {
    function escHtml(s) {
        return String(s)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    document.querySelectorAll('.wink-file-picker').forEach(function(picker) {
        var inputId = picker.dataset.inputId;
        var input   = document.getElementById(inputId);
        var listId  = inputId.replace('wink_doc_input_', 'wink_doc_list_');
        var listEl  = document.getElementById(listId);
        if (!input || !listEl) return;

        // DataTransfer holds the managed file collection submitted by the hidden input.
        var dt = new DataTransfer();

        function syncInputFiles() {
            try { input.files = dt.files; } catch(e) {}
        }

        picker._winkSyncFiles = syncInputFiles;

        function renderFiles() {
            listEl.innerHTML = '';
            for (var i = 0; i < dt.items.length; i++) {
                (function(idx) {
                    var f = dt.items[idx].getAsFile();
                    var chip = document.createElement('span');
                    chip.className = 'd-inline-flex align-items-center gap-1 px-2 py-1 rounded-pill';
                    chip.style.cssText = 'background:#e9ecef;color:#495057;font-size:0.75rem;max-width:200px;';

                    var icon = document.createElement('i');
                    icon.className = 'fa fa-file-o flex-shrink-0';

                    var nameSpan = document.createElement('span');
                    nameSpan.style.cssText = 'overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:130px;display:inline-block;';
                    nameSpan.textContent = f.name;
                    nameSpan.title = f.name;

                    var rmBtn = document.createElement('button');
                    rmBtn.type = 'button';
                    rmBtn.title = 'Remove ' + f.name;
                    rmBtn.style.cssText = 'background:none;border:none;padding:0 0 0 2px;cursor:pointer;color:#6c757d;font-size:0.85rem;line-height:1;flex-shrink:0;';
                    rmBtn.innerHTML = '&times;';
                    rmBtn.addEventListener('click', function() {
                        dt.items.remove(idx);
                        syncInputFiles();
                        renderFiles();
                    });

                    chip.appendChild(icon);
                    chip.appendChild(nameSpan);
                    chip.appendChild(rmBtn);
                    listEl.appendChild(chip);
                })(i);
            }
        }

        input.addEventListener('change', function(e) {
            Array.from(e.target.files || []).forEach(function(f) {
                // Skip duplicates by name
                var dup = false;
                for (var j = 0; j < dt.items.length; j++) {
                    if (dt.items[j].getAsFile().name === f.name) { dup = true; break; }
                }
                if (!dup) dt.items.add(f);
            });
            syncInputFiles();
            renderFiles();
        });

        renderFiles();
    });

    // ── Submit validator: required doc enforcement ──
    // Hidden inputs cannot receive browser focus for native validation.
    // Block submit and show an inline error if a required doc has no files.
    var _form = document.getElementById('wink-activation-form');
    if (_form) {
        _form.addEventListener('submit', function(ev) {
            document.querySelectorAll('.wink-file-picker').forEach(function(picker) {
                if (typeof picker._winkSyncFiles === 'function') {
                    picker._winkSyncFiles();
                }
            });
            var missing = [];
            document.querySelectorAll('.wink-file-real-input[data-required="1"]').forEach(function(inp) {
                if (!inp.files || inp.files.length === 0) {
                    missing.push(inp.dataset.docName || inp.name);
                    var picker = inp.closest('.wink-file-picker');
                    if (picker) picker.style.outline = '2px solid #dc3545';
                }
            });
            if (missing.length > 0) {
                ev.preventDefault();
                var errEl = document.getElementById('wink-doc-val-err');
                if (!errEl) {
                    errEl = document.createElement('div');
                    errEl.id = 'wink-doc-val-err';
                    errEl.className = 'alert alert-danger rounded-3 mb-3';
                    errEl.style.fontSize = '0.875rem';
                    var docList = document.querySelector('.wink-doc-list');
                    if (docList) {
                        docList.parentNode.insertBefore(errEl, docList);
                    }
                }
                errEl.textContent = 'Please attach a file for: ' + missing.join(', ');
                errEl.scrollIntoView({behavior: 'smooth', block: 'center'});
            } else {
                var old = document.getElementById('wink-doc-val-err');
                if (old) old.remove();
            }
        });
        // Clear error outline when user attaches a file
        document.addEventListener('change', function(ev) {
            if (ev.target && ev.target.classList.contains('wink-file-real-input')) {
                var p = ev.target.closest('.wink-file-picker');
                if (p) p.style.outline = '';
                var old2 = document.getElementById('wink-doc-val-err');
                if (old2) old2.remove();
            }
        });
    }
})();
